  8	import com.fream.back.domain.order.entity.OrderItem;
  9	import com.fream.back.domain.order.entity.OrderStatus;
 10	import com.fream.back.domain.order.exception.*;
 11	import com.fream.back.domain.order.repository.OrderRepository;
 12	import com.fream.back.domain.order.service.query.OrderBidQueryService;
 13	import com.fream.back.domain.payment.dto.PaymentRequestDto;
 14	import com.fream.back.domain.payment.entity.Payment;
 15	import com.fream.back.domain.payment.service.command.PaymentCommandService;
 16	import com.fream.back.domain.product.entity.ProductSize;
 17	import com.fream.back.domain.sale.entity.Sale;
 18	import com.fream.back.domain.sale.entity.SaleBid;
 19	import com.fream.back.domain.shipment.entity.OrderShipment;
 20	import com.fream.back.domain.shipment.service.command.OrderShipmentCommandService;
 21	import com.fream.back.domain.user.entity.User;
 22	import com.fream.back.domain.user.service.query.UserQueryService;
 23	import com.fream.back.domain.warehouseStorage.entity.WarehouseStatus;
 24	import com.fream.back.domain.warehouseStorage.entity.WarehouseStorage;
 25	import com.fream.back.domain.warehouseStorage.exception.WarehouseStorageException;
 26	import com.fream.back.domain.warehouseStorage.service.command.WarehouseStorageCommandService;
 27	import jakarta.persistence.EntityManager;
 28	import lombok.RequiredArgsConstructor;
 29	import lombok.extern.slf4j.Slf4j;
 30	import org.springframework.stereotype.Service;
 31	import org.springframework.transaction.annotation.Transactional;
 32	
 33	@Service
 34	@RequiredArgsConstructor
 35	@Slf4j
 36	public class OrderCommandService {
 37	
 38	    private final OrderRepository orderRepository;
 39	    private final PaymentCommandService paymentCommandService;
 40	    private final OrderShipmentCommandService orderShipmentCommandService;
 41	    private final OrderItemCommandService orderItemCommandService;
 42	    private final OrderBidQueryService orderBidQueryService;
 43	    private final UserQueryService userQueryService;
 44	    private final WarehouseStorageCommandService warehouseStorageCommandService;
 45	    private final AddressQueryService addressQueryService;
 46	    private final EntityManager entityManager;
 47	
 48	    /**
 49	     * 입찰에서 주문을 생성합니다.
 50	     *
 51	     * @param user 사용자 정보
 52	     * @param productSize 상품 사이즈 정보
 53	     * @param bidPrice 입찰 가격
 54	     * @return 생성된 주문
 55	     * @throws OrderCreationFailedException 주문 생성 실패 시
 56	     * @throws InvalidBidPriceException 입찰 가격이 유효하지 않을 경우
 57	     */
 58	    @Transactional
 59	    public Order createOrderFromBid(User user, ProductSize productSize, int bidPrice) {
 60	        try {
 61	            // 입력값 검증
 62	            if (user == null) {
 63	                throw new InvalidOrderDataException("사용자 정보가 없습니다.");
 64	            }
 65	            if (productSize == null) {
 66	                throw new ProductSizeNotFoundException("상품 사이즈 정보가 없습니다.");
 67	            }
 68	            if (bidPrice <= 0) {
 69	                throw new InvalidBidPriceException("입찰 가격은 0보다 커야 합니다. 현재 가격: " + bidPrice);
 70	            }
 71	
 72	            // 1. OrderItem 생성
 73	            OrderItem orderItem = orderItemCommandService.createOrderItem(null, productSize, bidPrice);
 74	
 75	            // 2. Order 생성
 76	            Order order = Order.builder()
 77	                    .user(user)
 78	                    .totalAmount(bidPrice) // 입찰가를 총 금액으로 설정
 79	                    .discountAmount(0) // 초기값은 0
 80	                    .usedPoints(0) // 초기값은 0
 81	                    .status(OrderStatus.PENDING_PAYMENT) // 결제 대기 상태
 82	                    .build();
 83	
 84	            // 3. OrderItem과 연관 설정
 85	            order.addOrderItem(orderItem);
 86	
 87	            // 4. Order 저장
 88	            return orderRepository.save(order);
 89	        } catch (Exception e) {
 90	            if (e instanceof OrderException) {
 91	                throw e;
 92	            }
 93	            log.error("주문 생성 중 오류 발생: {}", e.getMessage(), e);
 94	            throw new OrderCreationFailedException("입찰에서 주문 생성 중 오류가 발생했습니다: " + e.getMessage(), e);
 95	        }
 96	    }
 97	
 98	    /**
 99	     * 주문에 대한 결제 및 배송 정보를 처리합니다.
100	     *
101	     * @param orderId 주문 ID
102	     * @param userEmail 사용자 이메일
103	     * @param requestDto 결제 및 배송 요청 정보
104	     * @throws OrderNotFoundException 주문을 찾을 수 없는 경우
105	     * @throws OrderAccessDeniedException 주문에 대한 접근 권한이 없는 경우
106	     * @throws OrderPaymentProcessingFailedException 결제 처리 실패 시
107	     * @throws OrderShipmentProcessingFailedException 배송 처리 실패 시
108	     * @throws OrderWarehouseStorageProcessingFailedException 창고 보관 처리 실패 시
109	     * @throws InvalidPaymentShipmentDataException 결제 및 배송 정보가 유효하지 않은 경우
110	     */
111	    @Transactional
112	    public void processPaymentAndShipment(Long orderId, String userEmail, PayAndShipmentRequestDto requestDto) {
113	        if (orderId == null) {
114	            throw new InvalidOrderDataException("주문 ID가 없습니다.");
115	        }
116	        if (userEmail == null || userEmail.trim().isEmpty()) {
117	            throw new OrderAccessDeniedException("사용자 정보가 없습니다.");
118	        }
119	        if (requestDto == null) {
120	            throw new InvalidPaymentShipmentDataException("결제 및 배송 정보가 없습니다.");
121	        }
122	
123	        try {
124	            // 1. User 및 Order 조회
125	            User user = userQueryService.findByEmail(userEmail);
126	            Order order = orderRepository.findById(orderId)
127	                    .orElseThrow(() -> new OrderNotFoundException("해당 주문을 찾을 수 없습니다(ID: " + orderId + ")"));
128	
129	            // 접근 권한 확인
130	            if (!order.getUser().getId().equals(user.getId())) {
131	                throw new OrderAccessDeniedException("해당 사용자는 이 주문을 처리할 권한이 없습니다.");
132	            }
133	
134	            // 주문 정보 유효성 검사
135	            validatePaymentShipmentRequest(requestDto);
136	
137	            try {
138	                // 2. 결제 처리
139	                Payment payment = paymentCommandService.processPayment(order, user, requestDto.getPaymentRequest());
140	                order.assignPayment(payment);
141	            } catch (Exception e) {
142	                log.error("결제 처리 중 오류 발생: {}", e.getMessage(), e);
143	                throw new OrderPaymentProcessingFailedException("결제 처리 중 오류가 발생했습니다: " + e.getMessage(), e);
144	            }
145	
146	            try {
147	                // 3. 배송 정보 생성
148	                OrderShipment shipment = orderShipmentCommandService.createOrderShipment(
149	                        order,
150	                        requestDto.getReceiverName(),
151	                        requestDto.getReceiverPhone(),
152	                        requestDto.getPostalCode(),
153	                        requestDto.getAddress()
154	                );
155	                order.assignOrderShipment(shipment);
156	            } catch (Exception e) {
157	                log.error("배송 정보 처리 중 오류 발생: {}", e.getMessage(), e);
158	                throw new OrderShipmentProcessingFailedException("배송 정보 처리 중 오류가 발생했습니다: " + e.getMessage(), e);
159	            }
160	
161	            try {
162	                // 4. 상태 업데이트
163	                if (requestDto.isWarehouseStorage()) {
164	                    // 창고 보관일 경우
165	                    order.updateStatus(OrderStatus.PAYMENT_COMPLETED);
166	                    order.updateStatus(OrderStatus.PREPARING);
167	                    order.updateStatus(OrderStatus.IN_WAREHOUSE);
168	
169	                    // 창고 보관 처리 추가
170	                    WarehouseStorage warehouseStorage = warehouseStorageCommandService.createOrderStorage(order, user);
171	                    order.assignWarehouseStorage(warehouseStorage);
172	                    order.updateStatus(OrderStatus.COMPLETED);  // 주문 완료 상태로 변경
173	                } else {
174	                    // 실제 배송일 경우
175	                    order.updateStatus(OrderStatus.PAYMENT_COMPLETED);
176	                    order.updateStatus(OrderStatus.PREPARING);
177	                }
178	            } catch (WarehouseStorageException e) {
179	                log.error("창고 보관 처리 중 오류 발생: {}", e.getMessage(), e);
180	                throw new OrderWarehouseStorageProcessingFailedException("창고 보관 처리 중 오류가 발생했습니다: " + e.getMessage(), e);
181	            } catch (Exception e) {
182	                log.error("주문 상태 업데이트 중 오류 발생: {}", e.getMessage(), e);
183	                throw new OrderStatusUpdateFailedException("주문 상태 업데이트 중 오류가 발생했습니다: " + e.getMessage(), e);
184	            }
185	
186	            // 5. OrderBid 상태 업데이트
187	            try {
188	                orderBidQueryService.findById(orderId).ifPresent(orderBid -> {
189	                    orderBid.updateStatus(BidStatus.MATCHED);
190	                });
191	            } catch (Exception e) {
192	                log.error("주문 입찰 상태 업데이트 중 오류 발생: {}", e.getMessage(), e);
193	                // 중요 정보 처리가 완료되었으므로 예외를 던지지 않고 로그만 남김
194	            }
195	        } catch (Exception e) {
196	            if (e instanceof OrderException) {
197	                throw e;
198	            }
199	            log.error("결제 및 배송 처리 중 오류 발생: {}", e.getMessage(), e);
200	            throw new OrderPaymentProcessingFailedException("결제 및 배송 처리 중 예상치 못한 오류가 발생했습니다: " + e.getMessage(), e);
201	        }
202	    }
203	
204	    /**
205	     * 즉시 구매 주문을 생성합니다.
206	     *
207	     * @param buyer 구매자 정보
208	     * @param saleBid 판매 입찰 정보
209	     * @param addressId 배송지 ID
210	     * @param isWarehouseStorage 창고 보관 여부
211	     * @param paymentRequest 결제 요청 정보
212	     * @return 생성된 주문
213	     * @throws OrderCreationFailedException 주문 생성 실패 시
214	     * @throws SaleBidNotFoundException 판매 입찰을 찾을 수 없는 경우
215	     * @throws InvalidOrderDataException 주문 정보가 유효하지 않은 경우
216	     * @throws OrderPaymentProcessingFailedException 결제 처리 실패 시
217	     * @throws OrderWarehouseStorageProcessingFailedException 창고 보관 처리 실패 시
218	     */
219	    @Transactional
220	    public Order createInstantOrder(User buyer, SaleBid saleBid, Long addressId,
221	                                    boolean isWarehouseStorage, PaymentRequestDto paymentRequest) {
222	        try {
223	            // 입력값 검증
224	            if (buyer == null) {
225	                throw new InvalidOrderDataException("구매자 정보가 없습니다.");
226	            }
227	            if (saleBid == null) {
228	                throw new SaleBidNotFoundException("판매 입찰 정보가 없습니다.");
229	            }
230	            if (addressId == null) {
231	                throw new InvalidOrderDataException("배송지 정보가 없습니다.");
232	            }
233	            if (paymentRequest == null) {
234	                throw new InvalidPaymentShipmentDataException("결제 정보가 없습니다.");
235	            }
236	
237	            // 1. 주소 조회
238	            AddressResponseDto address = addressQueryService.getAddress(buyer.getEmail(), addressId);
239	
240	            // 2. Order 생성
241	            Order order = Order.builder()
242	                    .user(buyer)
243	                    .totalAmount(saleBid.getBidPrice())
244	                    .status(OrderStatus.PENDING_PAYMENT)
245	                    .build();
246	
247	            order = orderRepository.save(order);
248	
249	            // PaymentRequest에 OrderId 설정
250	            paymentRequest.setOrderId(order.getId());
251	            log.debug("결제 요청 정보: {}", paymentRequest);
252	
253	            // 3. OrderItem 추가
254	            try {
255	                OrderItem orderItem = orderItemCommandService.createOrderItem(order, saleBid.getProductSize(), saleBid.getBidPrice());
256	                order.addOrderItem(orderItem);
257	            } catch (Exception e) {
258	                log.error("주문 항목 생성 중 오류 발생: {}", e.getMessage(), e);
259	                throw new OrderItemCreationFailedException("주문 항목 생성 중 오류가 발생했습니다: " + e.getMessage(), e);
260	            }
261	
262	            // 4. 배송 정보 생성 및 연관 설정
263	            try {
264	                OrderShipment orderShipment = orderShipmentCommandService.createOrderShipment(
265	                        order,
266	                        address.getRecipientName(),
267	                        address.getPhoneNumber(),
268	                        address.getZipCode(),
269	                        address.getAddress()
270	                );
271	                order.assignOrderShipment(orderShipment);
272	            } catch (Exception e) {
273	                log.error("배송 정보 생성 중 오류 발생: {}", e.getMessage(), e);
