  1	package com.fream.back.domain.order.service.command;
  2	
  3	import com.fream.back.domain.order.entity.BidStatus;
  4	import com.fream.back.domain.order.entity.Order;
  5	import com.fream.back.domain.order.entity.OrderBid;
  6	import com.fream.back.domain.order.exception.*;
  7	import com.fream.back.domain.order.repository.OrderBidRepository;
  8	import com.fream.back.domain.payment.dto.PaymentRequestDto;
  9	import com.fream.back.domain.product.entity.ProductSize;
 10	import com.fream.back.domain.product.service.productSize.ProductSizeQueryService;
 11	import com.fream.back.domain.sale.entity.Sale;
 12	import com.fream.back.domain.sale.entity.SaleBid;
 13	import com.fream.back.domain.sale.service.query.SaleBidQueryService;
 14	import com.fream.back.domain.user.entity.User;
 15	import com.fream.back.domain.user.service.query.UserQueryService;
 16	import lombok.RequiredArgsConstructor;
 17	import lombok.extern.slf4j.Slf4j;
 18	import org.springframework.stereotype.Service;
 19	import org.springframework.transaction.annotation.Transactional;
 20	
 21	/**
 22	 * 주문 입찰 명령 서비스
 23	 */
