            // 처리 시간 로깅
            Instant end = Instant.now();
            Duration duration = Duration.between(start, end);
            log.debug("PortOne API 테스트 결제 처리 시간: {}ms", duration.toMillis());

            return impUid;
        } catch (PaymentException e) {
